function historyHtml(d){
  const h=[...(d.history||[])];
  if(!h.length)return '<p class="small muted">暂未产生处理记录，保存与提审后将在这里保留历史。</p>';
  const events={CREATED:'创建申请',DRAFT_CREATED:'创建工作稿',DRAFT_SAVED:'保存草稿',DRAFT_UPDATED:'更新申报内容',REVISION_CREATED:'创建内容版本',UPDATED:'修改申请',SUBMITTED:'正式提交',WITHDRAWN:'撤回申请',PEER_APPROVED:'学生审查通过',COUNSELOR_APPROVED:'辅导员审核通过',REVIEW_APPROVE:'审核批准',REVIEW_REJECT:'审核驳回',REJECTED:'驳回申请',APPROVED:'审核通过',SUPERSEDED:'被更高优先级奖项替代',AWARD_SUPERSEDED:'被更高优先级奖项替代',RESTORED:'恢复原申请状态',AWARD_RESTORED:'恢复原申请状态',FILE_ADDED:'添加证明材料',CROP_ADDED:'添加关键证据',AI_APPLIED:'应用AI建议'};
  return `<div class="timeline">${h.slice().reverse().map(x=>`<div class="timeline-item"><h4>${esc(events[x.event_type]||x.label||x.event_type||x.action||'处理记录')}${x.to_state?` · ${esc(stateNames[x.to_state]||x.to_state)}`:''}</h4><p>${esc(x.actor_name || x.actor_name_snapshot || (x.actor_type==='SYSTEM'?'系统自动处理':''))}${x.comment || x.detail_json?.comment ? ' · '+esc(x.comment || x.detail_json.comment):''}${x.detail_json?.reason?' · '+esc(x.detail_json.reason):''}</p><time>${date(x.occurred_at || x.decided_at || x.created_at)}</time></div>`).join('')}</div>`;
}
async function saveApplication(){
  const form=$('#application-form');if(!form || !S.detail.can_edit)return S.detail;
  if(!form.reportValidity())throw new Error('请先完善必填的申报信息。');
  const p={...(S.detail.revision?.payload_json||{})};
  for(const key of ['edition_key','track_key','group_key','work_key','award_level','volunteer_hours','subtype','note'])if(form.elements[key]){const v=form.elements[key].value;if(key==='volunteer_hours'){if(v==='')delete p[key];else p[key]=v;}else p[key]=v;}
  const result=await api(`/applications/${S.detail.id}`,{method:'PUT',body:{title:form.elements.title.value.trim(),requested_score:form.elements.requested_score.value,activity_id:form.elements.activity_id.value || null,payload_json:p}});
  S.detail=result;return result;
}
async function uploadFiles(files){
  if(!files.length)return;const zone=$('#upload-zone');if(zone)zone.innerHTML='<div class="spinner"></div><p>正在保存并处理文件…</p>';
  try{if($('#application-form')?.elements.title.value.trim())await saveApplication();let success=0;for(const file of validLocalFiles(files)){if(!/\.(pdf|png|jpe?g)$/i.test(file.name)){toast(`${file.name}：仅支持 PDF / JPG / PNG`,true);continue;}const form=new FormData();form.append('file',file);try{await api(`/applications/${S.detail.id}/files`,{method:'POST',body:form});success++;}catch(e){toast(`${file.name}：${e.message}`,true);}}if(success)toast(`已上传 ${success} 份证明材料`);await refresh();}catch(e){toast(e.message,true);await refresh();}
}
