  try{const list=arr(await api('/applications'+query({scope:'mine'})));if($('#related-application'))$('#related-application').innerHTML='<option value="">不指定，由系统核对明确的项目信息</option>'+list.filter(a=>a.id!==S.detail.id && a.category_id===S.detail.category_id && ['APPROVED','PENDING_PEER','PENDING_COUNSELOR'].includes(a.state)).map(a=>`<option value="${esc(a.id)}">${esc(a.title)} · ${fmt(a.requested_score)}分 · ${esc(stateNames[a.state])}</option>`).join('');}catch{/* Optional relation list can be omitted. */}
  $('#confirm-submit').onclick=e=>buttonTask(e.currentTarget,async()=>{try{const body={expected_version:S.detail.lock_version};const related=$('#related-application').value;if(related)body.related_application_id=related;await api(`/applications/${S.detail.id}/submit`,{method:'POST',body});closeModal();toast('申请已正式提交，等待学生审查');await refresh();}catch(err){modalError(err.message);}});
