function legacyCropModal(pageId){
  const file=(S.detail.files||[]).find(f=>(f.pages||[]).some(p=>p.id===pageId));const page=file?.pages.find(p=>p.id===pageId);if(!page)return;
  const canEdit=S.detail.can_edit===true;
  showModal(canEdit?'框选关键证据':'预览证明材料',`<p class="muted small mb16">${esc(file.original_name)} · 第 ${Number(page.page_index)||1} 页</p>${canEdit?`<div class="crop-controls"><select id="crop-kind" aria-label="证据类别"><option value="VALIDITY">文件有效性证据</option><option value="PARTICIPATION">本人参与证明</option></select><button class="btn sm primary" id="crop-select-mode">${icon('crop')}框选证据</button><button class="btn sm" id="crop-mask-mode">${icon('shield')}添加遮挡</button><button class="btn sm" id="crop-reset">清除选区</button></div>`:''}<div class="crop-canvas-wrap"><canvas id="crop-canvas" aria-label="证明原页，可拖动框选证据"></canvas></div><p class="crop-helper">${canEdit?'在图片上拖动框选证据区域，再点击保存。可切换“添加遮挡”，对截图内学号或其他隐私区域补充遮挡。原始材料和审核用截图保持完整；公示使用脱敏版本。':'证明原件仅供授权用户查看。'}</p><div class="crop-preview-label" id="crop-coordinates">正在加载证明页…</div>`,`<button class="btn" data-action="close-modal">关闭</button>${canEdit?'<button class="btn primary" id="crop-save" disabled>保存证据截图</button>':''}`,true);
  const canvas=$('#crop-canvas');const ctx=canvas.getContext('2d');const image=new Image();let box=null,masks=[],start=null,drag=null,mode='box';
  function rect(a,b){let x=Math.min(a.x,b.x),y=Math.min(a.y,b.y),w=Math.abs(a.x-b.x),h=Math.abs(a.y-b.y);return [Math.round(x),Math.round(y),Math.round(w),Math.round(h)];}
  function paint(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);if(box){ctx.fillStyle='#102a4340';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,box[0],box[1],box[2],box[3],box[0],box[1],box[2],box[3]);ctx.strokeStyle='#168b82';ctx.lineWidth=Math.max(2,canvas.width/500);ctx.strokeRect(...box);}for(const m of masks){ctx.fillStyle='#173c57b0';ctx.fillRect(...m);}if(drag&&start){const b=rect(start,drag);ctx.fillStyle=mode==='mask'?'#173c5770':'#168b8220';ctx.fillRect(...b);ctx.strokeStyle=mode==='mask'?'#375c78':'#168b82';ctx.lineWidth=Math.max(2,canvas.width/500);ctx.strokeRect(...b);}}
  image.onload=()=>{canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;paint();$('#crop-coordinates').textContent=canEdit?'请选择证据区域。':`${canvas.width} × ${canvas.height} 像素`;};image.onerror=()=>{$('#crop-coordinates').textContent='证明页加载失败，请关闭后重试。';};image.src=page.url || page.image_url || '/api/pages/'+page.id;
  if(!canEdit)return;
  function point(e){const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(canvas.width,(e.clientX-r.left)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(e.clientY-r.top)*canvas.height/r.height))};}
  canvas.onpointerdown=e=>{start=point(e);drag=start;canvas.setPointerCapture(e.pointerId);e.preventDefault();};canvas.onpointermove=e=>{if(!start)return;drag=point(e);paint();};canvas.onpointerup=e=>{if(!start)return;const b=rect(start,point(e));if(b[2]>=4&&b[3]>=4){if(mode==='mask')masks.push(b);else box=b;}start=null;drag=null;paint();$('#crop-save').disabled=!box;$('#crop-coordinates').textContent=box?`选区 ${box[2]} × ${box[3]} 像素，已添加 ${masks.length} 处额外遮挡。`:'请选择证据区域。';};canvas.onpointercancel=()=>{start=null;drag=null;paint();};
  $('#crop-select-mode').onclick=()=>{mode='box';$('#crop-select-mode').classList.add('primary');$('#crop-mask-mode').classList.remove('primary');};$('#crop-mask-mode').onclick=()=>{mode='mask';$('#crop-mask-mode').classList.add('primary');$('#crop-select-mode').classList.remove('primary');};$('#crop-reset').onclick=()=>{box=null;masks=[];$('#crop-save').disabled=true;$('#crop-coordinates').textContent='请选择证据区域。';paint();};
  $('#crop-save').onclick=e=>buttonTask(e.currentTarget,async()=>{try{await api(`/applications/${S.detail.id}/crops`,{method:'POST',body:{page_id:page.id,evidence_type:$('#crop-kind').value,box,masks}});closeModal();toast('关键证据已保存');await refresh();}catch(err){modalError(err.message);}});
}

