function activityEligibility(a){return a.eligibilities || a.eligibility_versions || a.qualifications || [];}
function drawActivities(){
  const search=($('#activity-search')?.value||'').toLowerCase();const list=S.activities.filter(a=>(a.canonical_name+' '+(a.aliases||[]).map(x=>typeof x==='string'?x:x.alias).join(' ')).toLowerCase().includes(search)&&(!S.activityFilter||activityEligibility(a).some(e=>e.decision===S.activityFilter)));
  $('#activity-list').innerHTML=list.length?list.map(a=>`<article class="card activity-card"><div class="row between"><h3>${esc(a.canonical_name)}</h3>${isCounselor()?`<button class="text-action" data-action="edit-activity" data-id="${esc(a.id)}">维护认定</button>`:''}</div><div class="activity-aliases">别名：${esc((a.aliases||[]).map(x=>typeof x==='string'?x:x.alias).join('、')||'暂无')}</div><div class="activity-meta">${activityEligibility(a).length?activityEligibility(a).map(e=>`<div class="row wrap gap6 mt8"><span class="tag ${e.decision==='VALID'?'success':e.decision==='INVALID'?'danger':''}">${esc(({VALID:'有效',INVALID:'无效',REMOVED:'已移除'})[e.decision]||e.decision)}</span><span>${esc(S.boot.categories.find(c=>c.id===e.category_id)?.name||e.category_name||'适用类别')}</span><span class="muted">${esc([S.boot.years.find(y=>y.id===e.academic_year_id)?.name,e.edition_key,e.track_key,e.group_key].filter(Boolean).join(' / ')||'通用范围')}</span></div>`).join(''):'<span class="tag">尚无资格认定</span>'}</div>${a.description?`<p class="small muted">${esc(a.description)}</p>`:''}${isCounselor()?`<div class="row between mt16"><button class="text-action" data-action="activity-impact" data-id="${esc(a.id)}">查看受影响的历史申请</button><button class="text-action danger-text" data-action="delete-activity" data-id="${esc(a.id)}">移除认定</button></div>`:''}</article>`).join(''):`<div class="card" style="grid-column:1/-1">${empty('暂无匹配活动','可搜索其他活动名称，未认定的活动由辅导员进一步审核。')}</div>`;
}
function activityModal(activity=null){
  const eligibility=activity?activityEligibility(activity)[0]||{}:{};
  showModal(activity?'维护活动资格':'新增活动资格',`<form id="activity-form" class="form-grid"><div class="field span2"><label for="activity-name">规范活动名称</label><input id="activity-name" name="canonical_name" required maxlength="255" value="${esc(activity?.canonical_name||'')}" placeholder="例如：蓝桥杯全国软件和信息技术专业人才大赛"></div><div class="field span2"><label for="activity-alias">别名（逗号或换行分隔）</label><textarea id="activity-alias" name="aliases" placeholder="蓝桥杯大赛，蓝桥杯竞赛">${esc((activity?.aliases||[]).map(x=>typeof x==='string'?x:x.alias).join('，'))}</textarea></div><div class="field"><label for="activity-category">适用加分类别</label><select id="activity-category" name="category_id" required>${options(S.boot.categories,eligibility.category_id)}</select></div><div class="field"><label for="activity-decision">资格认定</label><select id="activity-decision" name="decision"><option value="VALID" ${eligibility.decision==='VALID'?'selected':''}>有效</option><option value="INVALID" ${eligibility.decision==='INVALID'?'selected':''}>无效</option><option value="REMOVED">移除此范围认定</option></select></div><div class="field span2"><label for="activity-year">适用学年（可选）</label><select id="activity-year" name="academic_year_id">${options(S.boot.years,eligibility.academic_year_id,'name','不限学年')}</select></div>${[['edition_key','届次'],['track_key','赛道'],['group_key','组别']].map(([k,n])=>`<div class="field"><label for="eligibility-${k}">${n}（可选）</label><input id="eligibility-${k}" name="${k}" value="${esc(eligibility[k]||'')}" maxlength="100" placeholder="留空表示不限"></div>`).join('')}<div class="field span2"><label for="activity-reason">认定说明</label><textarea id="activity-reason" name="reason" maxlength="2000" placeholder="可记录适用依据与限制">${esc(eligibility.reason||'')}</textarea></div></form><div class="notice mt16">${icon('info')}<span>每次保存会保留认定版本。变更为无效后，可查看历史受影响申请，由辅导员逐项复核。</span></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="save-activity">保存认定</button>`);
  $('#save-activity').onclick=e=>buttonTask(e.currentTarget,async()=>{const f=$('#activity-form');if(!f.reportValidity())return;const body={canonical_name:f.elements.canonical_name.value.trim(),aliases:f.elements.aliases.value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean),category_id:f.elements.category_id.value,decision:f.elements.decision.value,academic_year_id:f.elements.academic_year_id.value||null,reason:f.elements.reason.value};for(const k of ['edition_key','track_key','group_key'])body[k]=f.elements[k].value.trim()||null;try{await api('/activities'+(activity?'/'+activity.id:''),{method:activity?'PUT':'POST',body});closeModal();toast('活动认定已保存');await refresh();}catch(err){modalError(err.message);}});
}
async function activityImpact(id){
  const data=arr(await api(`/activities/${id}/impact`));showModal('受影响的历史申请',`<div class="notice mb16">${icon('info')}<span>以下申请不因活动库变化自动撤销。请结合新认定逐项复核，必要时驳回已通过条目。</span></div>${data.length?applicationTable(data):empty('没有受影响的历史申请','当前授权班级范围内暂无相关记录。')}`,`<button class="btn" data-action="close-modal">关闭</button>`,true);
  $$('[data-action="detail"]',$('.modal')).forEach(b=>b.onclick=async()=>{closeModal();await go('detail',{id:b.dataset.id,from:'activities'});});
}
function deleteActivityModal(id){
  showModal('移除活动认定','<p class="muted small">移除后该活动的资格将按未认定处理。历史申请及此前审核记录保留，不会自动撤销已通过条目。</p>',`<button class="btn" data-action="close-modal">取消</button><button class="btn danger" id="delete-activity-confirm">移除认定</button>`);
  $('#delete-activity-confirm').onclick=e=>buttonTask(e.currentTarget,async()=>{try{await api(`/activities/${id}`,{method:'DELETE'});closeModal();toast('认定已移除，历史记录保留');await refresh();}catch(err){modalError(err.message);}});
}

async function renderScores(seq){
  const data=await api('/scores'+query());if(seq!==S.renderSequence)return;S.scoreData=data;
  $('#page').innerHTML=pageTitle('成绩汇总',`${data.class?.name||''} · ${data.year?.name||''} · 只统计当前有效、已通过的加分条目。`,hasPermission('export.read')?`<button class="btn primary" data-action="export">${icon('download')}导出 Excel 汇总表</button>`:'')+`<div class="notice mb16">${icon('info')}<span>默认基准分 70，扣分记 0。各类别执行封顶，同一竞赛项目及兼任职务按规则取最高；无申报学生也计入班级汇总。</span></div>${scoreTable(data)}<p class="small muted mt12">点击“查看条目”可核查分类明细和关键证据。导出保留示例的 15 列与双层表头。</p>`;
}
function scoreTable(data){
  const members=data.members||[],cats=S.boot.categories||[];
  if(!members.length)return `<div class="card">${empty('当前班级没有学生','请联系管理员检查班级与学年归属。')}</div>`;
  return `<div class="card"><div class="table-wrap"><table class="score-table"><thead><tr><th>学生姓名</th><th>基准分</th>${cats.map(c=>`<th>${esc(c.name)}<br><span class="small">上限 ${Number(c.default_cap)} 分</span></th>`).join('')}<th>德育总分</th><th>操作</th></tr></thead><tbody>${members.map(m=>`<tr><td><div class="table-title">${esc(m.display_name||m.student_name)}</div>${m.student_number?`<div class="table-sub">${esc(m.student_number)}</div>`:''}</td><td>${fmt(m.baseline??70)}</td>${cats.map(c=>{const v=(m.categories||[]).find(x=>x.id===c.id||x.category_id===c.id||x.code===c.code);return `<td>${fmt(v?.score??0)}</td>`;}).join('')}<td class="score-num big">${fmt(m.total)}</td><td><button class="text-action" data-action="score-detail" data-id="${esc(m.student_id || m.user_id || m.id)}">查看条目</button></td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>共 ${members.length} 位学生</span><span>实时汇总 · 两位小数</span></div></div>`;
}
function scoreDetailModal(id){
  const member=S.scoreData?.members?.find(m=>[m.student_id,m.user_id,m.id].includes(id));if(!member)return;
  showModal(`${member.display_name||member.student_name} · 加分明细`,`<div class="row between mb16"><span class="muted small">基准分 ${fmt(member.baseline??70)} 分</span><span class="score-num big">总分 ${fmt(member.total)}</span></div><div class="score-detail-categories">${(member.categories||[]).map(c=>`<section class="score-category"><header class="score-category-head"><strong>${esc(c.name)}</strong><span>${fmt(c.score)} / ${Number(c.cap??c.default_cap)} 分</span></header><div class="score-category-items">${(c.items||[]).length?(c.items||[]).map(i=>`<article class="score-item"><div class="row between"><span class="strong small">${esc(i.title || '加分条目')}</span><span class="score-num">${fmt(i.score ?? i.requested_score)} 分</span></div><p class="small muted mt8">学生审查员：${esc(i.reviewer_name || i.peer_reviewer_name || '—')}</p>${i.student_modified_score?'<span class="tag purple mt8">学生手动修改过计分</span>':''}${i.crops?.length?`<div class="crop-grid">${i.crops.map(cr=>`<a class="crop-image" href="${urlSafe(cr.public_url||cr.url)}" target="_blank" rel="noopener"><img loading="lazy" src="${urlSafe(cr.public_url||cr.url)}" alt="${cr.evidence_type==='VALIDITY'?'有效性证据':'参与证明'}"></a>`).join('')}</div>`:''}</article>`).join(''):'<p class="muted small">本类别暂无已通过条目。</p>'}</div></section>`).join('')}</div>`,`<button class="btn" data-action="close-modal">关闭</button>`,true);
}
async function renderPublicity(seq){
  let data;
  try{data=await api('/publicity'+query());}
  catch(e){if(e.status===403 && isCounselor()){data=await api('/scores'+query());}else if(e.status===403 && isStudent()){if(seq!==S.renderSequence)return;$('#page').innerHTML=pageTitle('班级公示','公示开放后，可查看本班同学已通过的条目、脱敏证据及学生审查员。')+`<div class="publicity-banner closed">${icon('lock')}<div><h2>本班本学年公示尚未开放</h2><p>全部正式申请审核完成后，辅导员可开启公示。请留意班级通知。</p></div></div><div class="card">${empty('等待辅导员开启公示','公示开放期间暂停正式提交新申请，仍可保存草稿。')}</div>`;return;}else throw e;}
  if(seq!==S.renderSequence)return;S.scoreData=data;const open=data.publicity?.is_open===true;
  $('#page').innerHTML=pageTitle('班级公示',`${data.class?.name||''} · ${data.year?.name||''} · 公示成绩根据已通过条目实时更新。`)+`<div class="publicity-banner ${open?'':'closed'}">${icon(open?'eye':'lock')}<div><h2>${open?'本班成绩正在公示':'本班公示尚未开放'}</h2><p>${open?'公示期间暂停正式提交和重提申请，可保存草稿。':'全部正式申请审核完成后方可开启，草稿不影响开启。'} 建议公示不少于三个工作日。</p>${open&&data.publicity?.opened_at?`<p>开启时间：${date(data.publicity.opened_at)}</p>`:''}</div>${isCounselor()?`<button class="btn ${open?'':'primary'}" data-action="publicity-toggle" data-open="${!open}">${open?'关闭公示':'开启公示'}</button>`:''}</div>${open?`<div class="notice mb16">${icon('shield')}<span>公示只展示已通过条目与脱敏截图，学号不向普通同学展示。辅导员仍可复核并驳回已通过条目，成绩会同步更新。</span></div>${scoreTable(data)}`:isCounselor()?`<div class="card">${empty('尚未向学生开放公示','请先完成当前所有待审正式申请，再开启公示。')}</div>`:''}`;
}
async function togglePublicity(btn){
  const open=btn.dataset.open==='true';
  showModal(open?'开启班级成绩公示':'关闭班级成绩公示',`<p class="muted small">${open?'开启前将检查本班所选学年没有待学生审查或待辅导员认定的正式申请。开启后暂停正式提交、重新提交和奖项替代。':'关闭后，学生可恢复正式提交和重新提交。请结合不少于三个工作日的公示建议安排关闭时间。'}</p>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="confirm-publicity">确认${open?'开启':'关闭'}</button>`);
  $('#confirm-publicity').onclick=e=>buttonTask(e.currentTarget,async()=>{try{await api('/publicity',{method:'PUT',body:{class_id:S.classId,year_id:S.yearId,is_open:open}});closeModal();toast(open?'公示已开启':'公示已关闭');await refresh();}catch(err){modalError(err.message);}});
}
async function downloadExport(button){
  await buttonTask(button,async()=>{const response=await fetch('/api/export'+query(),{credentials:'same-origin'});if(!response.ok){let d;try{d=await response.json();}catch{d={};}throw new Error(d.detail||'导出失败');}const blob=await response.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${S.boot.classes.find(c=>c.id===S.classId)?.name||'班级'}_${S.boot.years.find(y=>y.id===S.yearId)?.code||'学年'}_德育分汇总.xlsx`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),10000);toast('Excel 汇总表已导出');});
}

async function renderMembers(seq){
  if(!S.classId){$('#page').innerHTML=empty('暂无可查看的班级','请联系管理员配置班级。');return;}
  const data=await api(`/classes/${S.classId}/members`+query());if(seq!==S.renderSequence)return;S.memberData=data;
  $('#page').innerHTML=pageTitle('班级成员',`${data.class?.name||''} · ${data.year?.name||''} · 班长与审查员职责公开可查。`,hasRole('MONITOR')?`<button class="btn primary" data-action="manage-reviewers">${icon('users')}管理学生审查员</button>`:'')+`<div class="notice mb16">${icon('shield')}<span>每班设置一位班长与至少两位不同的学生审查员。每条申请只需一位非本人的审查员完成初审。</span></div><div class="member-grid">${(data.members||[]).map(m=>{const roles=(m.roles||[]).map(x=>typeof x==='string'?x:x.code);return `<div class="card member-card"><div class="avatar">${esc((m.display_name||m.name||'同学').slice(-2))}</div><div><h3>${esc(m.display_name||m.name)}${m.student_number?` <small class="muted mono">${esc(m.student_number)}</small>`:''}</h3><div class="tags">${roles.includes('MONITOR')?'<span class="tag info">班长</span>':''}${roles.includes('REVIEWER')?'<span class="tag success">学生审查员</span>':''}${!roles.some(r=>['MONITOR','REVIEWER'].includes(r))?'<span class="tag">学生</span>':''}</div></div></div>`;}).join('')}</div>`;
}
function reviewersModal(){
  const members=S.memberData?.members||[];showModal('管理本班学生审查员',`<div class="notice mb16">${icon('info')}<span>请至少选择两位不同的本班学生。班长可以同时担任审查员，但不能重复计数。</span></div><div class="checkbox-list">${members.map(m=>`<label class="checkbox-item"><input type="checkbox" name="reviewer" value="${esc(m.user_id||m.id)}" ${(m.roles||[]).some(r=>(typeof r==='string'?r:r.code)==='REVIEWER')?'checked':''}><span>${esc(m.display_name||m.name)}</span></label>`).join('')}</div><div class="checked-count mt12" id="reviewer-count"></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="save-reviewers">保存审查员</button>`);
  const count=()=>{$('#reviewer-count').textContent=`已选择 ${$$('input[name=reviewer]:checked').length} 人，至少需要 2 人`;};$$('input[name=reviewer]').forEach(x=>x.onchange=count);count();
  $('#save-reviewers').onclick=e=>buttonTask(e.currentTarget,async()=>{const ids=$$('input[name=reviewer]:checked').map(x=>x.value);if(ids.length<2){modalError('每班必须至少有两位不同的学生审查员。');return;}try{await api(`/classes/${S.classId}/reviewers`,{method:'PUT',body:{user_ids:ids}});closeModal();toast('审查员配置已更新');await refresh();}catch(err){modalError(err.message);}});
}

async function renderAdmin(seq){
  const tab=S.adminTab || 'users';
  $('#page').innerHTML=pageTitle('系统管理','统一管理账号、班级组织及角色权限。')+`<div class="admin-tabs">${[['users','账号管理'],['classes','班级与任职'],['roles','角色权限矩阵']].map(([v,n])=>`<button class="admin-tab ${v===tab?'active':''}" data-action="admin-tab" data-tab="${v}">${n}</button>`).join('')}</div><div id="admin-content">${loading()}</div>`;
  if(tab==='users'){
    const users=arr(await api('/admin/users'));if(seq!==S.renderSequence)return;S.adminUsers=users;
    $('#admin-content').innerHTML=`<div class="toolbar"><div class="muted small">共 ${users.length} 个账号 · 基础身份互斥</div><div class="row"><button class="btn sm" data-action="import-users">${icon('upload')}CSV 批量导入</button><button class="btn sm primary" data-action="new-user">${icon('plus')}创建账号</button></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>账号 / 姓名</th><th>基础身份</th><th>学号</th><th>所属班级</th><th>账号状态</th><th>操作</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="table-title">${esc(u.display_name)}</div><div class="table-sub mono">${esc(u.username)}</div></td><td><span class="tag ${u.base_identity==='ADMIN'?'purple':u.base_identity==='COUNSELOR'?'info':''}">${esc(roleNames[u.base_identity]||u.base_identity)}</span></td><td class="mono">${esc(u.student_number||u.student_profile?.student_number||'—')}</td><td>${esc(u.class_name||u.class?.name||(u.class_ids||[]).map(id=>S.boot.classes.find(c=>c.id===id)?.name||'').filter(Boolean).join('、')||'—')}</td><td><span class="tag ${u.status==='ACTIVE'?'success':''}">${u.status==='ACTIVE'?'启用':'停用'}</span></td><td><button class="text-action" data-action="edit-user" data-id="${esc(u.id)}">编辑账号</button></td></tr>`).join('')}</tbody></table></div></div>`;
  }else if(tab==='classes'){
    const users=arr(await api('/admin/users'));if(seq!==S.renderSequence)return;S.adminUsers=users;
    $('#admin-content').innerHTML=`<div class="toolbar"><span class="muted small">配置学生班级、班长、审查员与所带辅导员</span><button class="btn sm primary" data-action="new-class">${icon('plus')}新增班级</button></div><div class="notice mb16">${icon('info')}<span>保存班级任职时，会同时检查本班唯一班长和至少两位不同的审查员，避免出现中间缺员状态。</span></div><div class="member-grid">${(S.boot.classes||[]).map(c=>`<article class="card activity-card"><div class="cat-icon c1">${icon('school')}</div><h3 class="mt12">${esc(c.name)}</h3><p class="small muted mt8">${esc(c.program_name||c.code||'教学班级')}</p><button class="btn sm mt16" data-action="class-assignments" data-id="${esc(c.id)}">配置班级任职</button></article>`).join('')}</div>`;
  }else{
    const data=await api('/admin/roles');if(seq!==S.renderSequence)return;S.roleData=data;
    const roles=data.roles||[],permissions=data.permissions||[],matrix=data.matrix||[];
    $('#admin-content').innerHTML=`<div class="toolbar"><span class="admin-hint">每条授权的操作和范围相交后生效；班级范围、禁止自审、管理员不读材料等规则始终有效。</span><button class="btn sm primary" data-action="save-matrix">${icon('check')}保存权限矩阵</button></div><div class="card"><div class="table-wrap"><table class="matrix-table"><thead><tr><th>资源 / 操作</th>${roles.map(r=>`<th>${esc(r.name)}<br><span class="matrix-scope">${esc(r.code)}</span></th>`).join('')}</tr></thead><tbody>${permissions.map(p=>`<tr><td><div class="matrix-title">${esc(p.name)}</div><div class="table-sub mono">${esc(p.code)}</div></td>${roles.map(r=>{const m=matrix.find(x=>x.role_id===r.id&&x.permission_id===p.id);return `<td><label class="role-check"><input type="checkbox" data-matrix-role="${esc(r.id)}" data-matrix-permission="${esc(p.id)}" ${m?.is_allowed?'checked':''} aria-label="${esc(r.name)} ${esc(p.name)}"><select data-scope-role="${esc(r.id)}" data-scope-permission="${esc(p.id)}" aria-label="${esc(r.name)} ${esc(p.name)} 数据范围">${[['OWN','本人'],['CLASS','授权班级'],['LED_CLASSES','所带班级'],['CLASS_PUBLIC','本班公示'],['SYSTEM_METADATA','系统元数据']].map(([v,n])=>`<option value="${v}" ${v===(m?.data_scope || 'OWN')?'selected':''}>${n}</option>`).join('')}</select></label></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div>`;
  }
}
function userModal(user=null){
  const classes=S.boot.classes||[];
  showModal(user?'编辑系统账号':'创建系统账号',`<form id="user-form" class="form-grid"><div class="field"><label for="user-username">登录账号</label><input id="user-username" name="username" value="${esc(user?.username||'')}" required maxlength="80" ${user?'readonly class="disabled-field"':''}></div><div class="field"><label for="user-display-name">姓名</label><input id="user-display-name" name="display_name" value="${esc(user?.display_name||'')}" required maxlength="80"></div><div class="field"><label for="user-identity">基础身份</label><select id="user-identity" name="base_identity" ${user?'disabled':''}>${['STUDENT','COUNSELOR','ADMIN'].map(v=>`<option value="${v}" ${(user?.base_identity||'STUDENT')===v?'selected':''}>${roleNames[v]}</option>`).join('')}</select></div><div class="field"><label for="user-password">${user?'重置密码（留空不更改）':'初始密码'}</label><input id="user-password" name="password" type="password" autocomplete="new-password" minlength="8" ${user?'':'required'} placeholder="至少8位"></div><div class="field" id="student-number-field"><label for="user-student-number">学号</label><input id="user-student-number" name="student_number" value="${esc(user?.student_number||user?.student_profile?.student_number||'')}" maxlength="40"></div><div class="field" id="student-class-field"><label for="user-class">所属班级（调整所选学年）</label><select id="user-class" name="class_id">${options(classes,user?.class_by_year?.[S.yearId]||user?.current_class_id||user?.class_id||user?.class?.id||user?.class_ids?.[0],'name','请选择班级')}</select><div class="hint">仅调整顶部所选学年；该学年已有申请时不能转班，历史归属保留。</div></div><div class="field span2 hidden" id="counselor-classes-field"><label>所带班级</label><div class="checkbox-list">${classes.map(c=>`<label class="checkbox-item"><input type="checkbox" name="counselor_class" value="${esc(c.id)}" ${(user?.counselor_class_ids||[]).includes(c.id)?'checked':''}><span>${esc(c.name)}</span></label>`).join('')}</div></div>${user?`<div class="field span2"><label for="user-status">账号状态</label><select id="user-status" name="status"><option value="ACTIVE" ${user.status==='ACTIVE'?'selected':''}>启用</option><option value="DISABLED" ${user.status==='DISABLED'?'selected':''}>停用</option></select><div class="hint">若停用会影响班长唯一性或审查员人数，请先完成班级任职调整。</div></div>`:''}</form>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="save-user">保存账号</button>`);
  const sync=()=>{const identity=$('#user-identity').value;$('#student-number-field').classList.toggle('hidden',identity!=='STUDENT');$('#student-class-field').classList.toggle('hidden',identity!=='STUDENT');$('#counselor-classes-field').classList.toggle('hidden',identity!=='COUNSELOR');$('#user-student-number').required=identity==='STUDENT';$('#user-class').required=identity==='STUDENT';};$('#user-identity').onchange=sync;sync();
  $('#save-user').onclick=e=>buttonTask(e.currentTarget,async()=>{const f=$('#user-form');if(!f.reportValidity())return;const body={username:f.elements.username.value.trim(),display_name:f.elements.display_name.value.trim(),base_identity:f.elements.base_identity.value};if(f.elements.password.value)body.password=f.elements.password.value;if(body.base_identity==='STUDENT'){body.student_number=f.elements.student_number.value.trim();body.class_id=f.elements.class_id.value;body.academic_year_id=S.yearId;}if(body.base_identity==='COUNSELOR')body.counselor_class_ids=$$('input[name=counselor_class]:checked').map(x=>x.value);if(user)body.status=f.elements.status.value;try{await api('/admin/users'+(user?'/'+user.id:''),{method:user?'PUT':'POST',body});closeModal();toast('账号已保存');await refresh();}catch(err){modalError(err.message);}});
}
function importUsersModal(){
  showModal('批量导入账号',`<p class="admin-hint">上传 UTF-8 编码 CSV，第一行为字段名。学生填写学号及班级 ID；辅导员可另在组织管理中关联班级。</p><div class="selection-box mono mt16" style="overflow:auto">username,display_name,base_identity,password,student_number,class_id<br>student03,示例同学,STUDENT,Demo@2026,20260003,班级ID</div><div class="field mt16"><label for="users-csv">选择 CSV 文件</label><input type="file" accept=".csv" id="users-csv"></div><div class="field mt16"><label>可用班级 ID</label><div class="selection-box mono" style="max-height:180px;overflow:auto">${(S.boot.classes||[]).map(c=>`${esc(c.name)}：${esc(c.id)}`).join('<br>')}</div></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="import-users-confirm">上传并导入</button>`);
  $('#import-users-confirm').onclick=e=>buttonTask(e.currentTarget,async()=>{const file=$('#users-csv').files[0];if(!file){modalError('请选择 CSV 文件。');return;}const f=new FormData();f.append('file',file);try{const result=await api('/admin/import',{method:'POST',body:f});closeModal();toast(`账号导入完成${result?.count!==undefined?'，共 '+result.count+' 个':''}`);await refresh();}catch(err){modalError(err.message);}});
}
function classModal(){
  showModal('新增班级',`<form id="class-form" class="form-grid"><div class="field span2"><label for="class-name">班级名称</label><input id="class-name" name="name" required maxlength="80" placeholder="例如：软件2403"></div><div class="field"><label for="class-code">班级编码</label><input id="class-code" name="code" required maxlength="40" placeholder="例如：software2403"></div><div class="field"><label for="class-program">专业名称</label><input id="class-program" name="program_name" maxlength="80" placeholder="软件工程"></div><div class="field span2"><label for="class-cohort">入学年份（可选）</label><input id="class-cohort" name="cohort_year" type="number" min="2000" max="2100" placeholder="2024"></div></form><p class="admin-hint mt16">创建后请绑定本班学生，并一次性配置一位班长、至少两位审查员及辅导员。</p>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="save-class">创建班级</button>`);
  $('#save-class').onclick=e=>buttonTask(e.currentTarget,async()=>{const f=$('#class-form');if(!f.reportValidity())return;const body={name:f.elements.name.value.trim(),code:f.elements.code.value.trim(),program_name:f.elements.program_name.value.trim(),cohort_year:f.elements.cohort_year.value?Number(f.elements.cohort_year.value):null};try{await api('/admin/classes',{method:'POST',body});closeModal();await loadBootstrap();renderShell();await go('admin');toast('班级已创建，请完成账号和任职配置');}catch(err){modalError(err.message);}});
}
async function classAssignmentsModal(classId){
  const cls=S.boot.classes.find(c=>c.id===classId);let data;
  try{data=await api(`/classes/${classId}/members`+query());}catch{data={members:[]};}
  const students=data.members||[];const allUsers=S.adminUsers||arr(await api('/admin/users'));const counselors=allUsers.filter(u=>u.base_identity==='COUNSELOR');
  const monitor=students.find(m=>(m.roles||[]).some(r=>(typeof r==='string'?r:r.code)==='MONITOR'));
  showModal(`${cls?.name||'班级'} · 配置任职`,`<form id="assignments-form" class="form-grid"><div class="field span2"><label for="assignment-monitor">班长（恰好一位）</label><select id="assignment-monitor" name="monitor_id" required>${options(students.map(m=>({id:m.user_id||m.id,name:m.display_name||m.name})),monitor?.user_id||monitor?.id,'name','请选择班长')}</select></div><div class="field span2"><label>学生审查员（至少两位）</label><div class="checkbox-list">${students.map(m=>`<label class="checkbox-item"><input type="checkbox" name="assigned_reviewer" value="${esc(m.user_id||m.id)}" ${(m.roles||[]).some(r=>(typeof r==='string'?r:r.code)==='REVIEWER')?'checked':''}><span>${esc(m.display_name||m.name)}</span></label>`).join('')||'<p class="small muted">请先创建或绑定本班学生。</p>'}</div></div><div class="field span2"><label>所带辅导员</label><div class="checkbox-list">${counselors.map(u=>`<label class="checkbox-item"><input type="checkbox" name="assigned_counselor" value="${esc(u.id)}" ${(u.counselor_class_ids||[]).includes(classId)?'checked':''}><span>${esc(u.display_name)}</span></label>`).join('')}</div></div></form>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="save-assignments">保存班级任职</button>`);
  $('#save-assignments').onclick=e=>buttonTask(e.currentTarget,async()=>{const f=$('#assignments-form');if(!f.reportValidity())return;const body={monitor_id:f.elements.monitor_id.value,reviewer_ids:$$('input[name=assigned_reviewer]:checked').map(x=>x.value),counselor_ids:$$('input[name=assigned_counselor]:checked').map(x=>x.value)};if(body.reviewer_ids.length<2){modalError('至少选择两位不同的学生审查员。');return;}try{await api(`/admin/classes/${classId}/assignments`,{method:'PUT',body});closeModal();toast('班级任职已保存');await refresh();}catch(err){modalError(err.message);}});
}
async function saveMatrix(button){
  await buttonTask(button,async()=>{for(const role of S.roleData.roles){const permissions=$$('[data-matrix-role]').filter(x=>x.dataset.matrixRole===role.id).map(x=>({permission_id:x.dataset.matrixPermission,is_allowed:x.checked,data_scope:$$('[data-scope-role]').find(y=>y.dataset.scopeRole===role.id&&y.dataset.scopePermission===x.dataset.matrixPermission).value}));await api(`/admin/roles/${role.id}/permissions`,{method:'PUT',body:{permissions}});}toast('权限矩阵已保存');await refresh();});
}
function accountModal(){
  showModal('账号设置',`<div class="row"><div class="avatar">${esc(S.user.display_name?.slice(-2))}</div><div><h3>${esc(S.user.display_name)}</h3><p class="small muted">${esc(S.user.username)} · ${esc(roleLabel())}</p></div></div><div class="divider"></div><form id="password-form" class="form-grid"><div class="field span2"><label for="current-password">当前密码</label><input id="current-password" name="current_password" type="password" autocomplete="current-password" required></div><div class="field span2"><label for="new-password">新密码</label><input id="new-password" name="new_password" type="password" autocomplete="new-password" required minlength="8" placeholder="至少8位字符"></div><div class="field span2"><label for="repeat-password">再次输入新密码</label><input id="repeat-password" name="repeat_password" type="password" autocomplete="new-password" required minlength="8"></div></form>`,`<button class="btn" id="account-logout">退出登录</button><button class="btn primary" id="change-password">修改密码</button>`);
  $('#account-logout').onclick=async()=>{try{await api('/logout',{method:'POST',body:{}});S.user=null;S.csrf='';closeModal();renderLogin();}catch(e){modalError(e.message);}};
  $('#change-password').onclick=e=>buttonTask(e.currentTarget,async()=>{const f=$('#password-form');if(!f.reportValidity())return;if(f.elements.new_password.value!==f.elements.repeat_password.value){modalError('两次输入的新密码不一致。');return;}try{const result=await api('/password',{method:'POST',body:{current_password:f.elements.current_password.value,new_password:f.elements.new_password.value}});if(result?.csrf_token)S.csrf=result.csrf_token;closeModal();toast('密码已修改，请使用新密码登录。');await api('/logout',{method:'POST',body:{}}).catch(()=>{});S.user=null;S.csrf='';renderLogin();}catch(err){modalError(err.message);}});
}

document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modal-root').innerHTML&&closeModal();$('.sidebar')?.classList.remove('open');}});
window.addEventListener('hashchange',()=>{if(S.user)go(location.hash.slice(1)||'dashboard',{},false);});
